8	func TestChartResultVersionsAreIndependent(t *testing.T) {
9		dir := t.TempDir()
10		s, err := Open(dir)
11		if err != nil {
12			t.Fatal(err)
13		}
14		defer s.Close()
15		actor := InternalActor("dr-1")
16	
17		p, err := s.RegisterPatient(actor, "Alice")
18		if err != nil {
19			t.Fatal(err)
20		}
21		enc, err := s.AddEncounter(actor, p.ID, time.Now())
22		if err != nil {
23			t.Fatal(err)
24		}
25		rec, err := s.CreateDraft(actor, p.ID, enc.ID, Diagnosis, "initial dx")
26		if err != nil {
27			t.Fatal(err)
28		}
29		if _, err := s.ActivateRecord(actor, rec.ID); err != nil {
30			t.Fatal(err)
31		}
32		if _, err := s.CorrectRecord(actor, rec.ID, 1, "corrected dx", "typo"); err != nil {
33			t.Fatal(err)
34		}
35	
36		// First chart view; tamper with its version id list.
37		c1, err := s.Chart(actor, p.ID)
38		if err != nil {
39			t.Fatal(err)
40		}
41		if len(c1.Records) != 1 || len(c1.Records[0].Record.Versions) != 2 {
42			t.Fatalf("unexpected history: %+v", c1.Records)
43		}
44		orig := append([]ID(nil), c1.Records[0].Record.Versions...)
45		c1.Records[0].Record.Versions[0] = ""
46		c1.Records[0].Record.Versions[1] = "ver_other_record"
47	
48		// Second chart view must be unaffected.
49		c2, err := s.Chart(actor, p.ID)
50		if err != nil {
51			t.Fatal(err)
52		}
53		got := c2.Records[0].Record.Versions
54		if len(got) != 2 || got[0] != orig[0] || got[1] != orig[1] {
55			t.Fatalf("official history changed by local mutation: %v vs %v", got, orig)
56		}
57		if len(c2.Records[0].Versions) != 2 {
58			t.Fatalf("versions missing: %+v", c2.Records[0].Versions)
59		}
60	
61		// EncounterRecords view must also be unaffected.
62		er, err := s.EncounterRecords(actor, p.ID, enc.ID)
63		if err != nil {
64			t.Fatal(err)
65		}
66		if got := er[0].Record.Versions; got[0] != orig[0] || got[1] != orig[1] {
67			t.Fatalf("encounter view corrupted: %v", got)
68		}
69	
70		// Legal correction still works and preserves history.
71		v3, err := s.CorrectRecord(actor, rec.ID, 2, "final dx", "clarification")
72		if err != nil {
73			t.Fatal(err)
74		}
75		if v3.Number != 3 {
76			t.Fatalf("expected version 3, got %d", v3.Number)
77		}
78		c3, err := s.Chart(actor, p.ID)
79		if err != nil {
80			t.Fatal(err)
81		}
82		if len(c3.Records[0].Versions) != 3 {
83			t.Fatalf("history lost after correction: %+v", c3.Records[0].Versions)
84		}
85		// Stale version correction still conflicts.
86		if _, err := s.CorrectRecord(actor, rec.ID, 2, "x", "y"); err == nil {
87			t.Fatal("expected ErrConflict")
88		}
89	}
