1	package clinical
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 本文件为“返回结果隔离”约定补回归保障：调用方从 CreateExchange、幂等重试、
10	// GetExchange、ListExchanges、FetchPackage 拿到的交换、包内容与回执只是本次
11	// 操作的结果视图。调用方在本地修改手中的结果，既不能改写库内正式保存的交换
12	// （固化包、摘要、状态、回执），也不能波及另一份已经取得的结果；纯本地修改
13	// 不产生业务变更，也不新增审计事件。
14	
15	// ---- 测试自用的独立深拷贝与篡改工具 ----
16	//
17	// 刻意不调用生产代码的 cloneExchangeValue/clonePackage：预期基线由测试自行
18	// 深拷贝，这样即便生产拷贝退化为浅拷贝，基线仍保持创建时内容，隔离断言才能
19	// 真正抓住泄漏。
20	
21	// snapshotExchange 独立深拷贝一份交换作为预期基线（在篡改手中结果之前调用）。
22	func snapshotExchange(x Exchange) Exchange {
23		cp := x
24		recs := make([]PackagedRecord, len(x.Package.Records))
25		copy(recs, x.Package.Records)
26		cp.Package.Records = recs
27		if x.Receipt != nil {
28			r := *x.Receipt
29			cp.Receipt = &r
30		}
31		return cp
32	}
33	
34	// snapshotDelivery 独立深拷贝一份取包视图作为预期基线。
35	func snapshotDelivery(d PackageDelivery) PackageDelivery {
36		cp := d
37		recs := make([]PackagedRecord, len(d.Package.Records))
38		copy(recs, d.Package.Records)
39		cp.Package.Records = recs
40		return cp
41	}
42	
43	func recordsByID(recs []PackagedRecord) map[ID]PackagedRecord {
44		m := make(map[ID]PackagedRecord, len(recs))
45		for _, r := range recs {
46			m[r.RecordID] = r
47		}
48		return m
49	}
50	
51	// tamperExchangeResult 在调用方手中的交换上做尽可能广泛的本地修改：
52	// 状态、摘要、包头、首条记录的全部字段（内容/记录标识/版本标识/版本号等）、
53	// 记录集合（丢掉一条）以及回执（凭空伪造或覆盖既有回执）。
54	func tamperExchangeResult(x *Exchange) {
55		x.Status = ExchangeAccepted
56		x.Digest = "digest-tampered-by-caller"
57		x.Package.PatientID = "pat_tampered"
58		x.Package.ReceiverID = "rcv_tampered"
59		if len(x.Package.Records) > 0 {
60			x.Package.Records[0].EncounterID = "enc_tampered"
61			x.Package.Records[0].Category = Order
62			x.Package.Records[0].RecordID = "rec_tampered"
63			x.Package.Records[0].VersionID = "ver_tampered"
64			x.Package.Records[0].Version = 999
65			x.Package.Records[0].EffectiveAt = time.Date(2000, 1, 1, 0, 0, 0, 0, time.UTC)
66			x.Package.Records[0].Content = "调用方本地篡改的内容"
67		}
68		if len(x.Package.Records) > 1 {
69			// 调用方改动手中的记录集合（丢掉一条）。
70			x.Package.Records = x.Package.Records[:1]
71		}
72		x.Receipt = &Receipt{
73			Outcome:      ReceiptAccepted,
74			Reason:       "调用方在手中伪造的回执",
75			RegisteredAt: time.Date(2001, 2, 3, 4, 5, 6, 0, time.UTC),
76		}
